const HOY = "2026-06-04";

const FMAP = {};
FACTURAS.forEach(f => { FMAP[f.i] = f; });

let SIM = {};
let CFG = {base: HOY, plazoDef: 45};
try{
  const s = JSON.parse(localStorage.getItem('proy_sim') || 'null');
  if(s) SIM = s;
  const c = JSON.parse(localStorage.getItem('proy_cfg') || 'null');
  if(c) CFG = c;
}catch(e){}

function money(x){
  if(!x || Math.abs(x) < 0.005) return '$ 0,00';
  const neg = x < 0; x = Math.abs(x);
  let p = x.toFixed(2).split('.');
  p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (neg ? '-' : '') + '$ ' + p[0] + ',' + p[1];
}
function fday(iso){
  if(!iso) return 'sin fecha';
  const p = iso.split('-');
  return p[2] + '/' + p[1] + '/' + p[0];
}
function esc(s){
  return String(s == null ? '' : s).replace(/[&<>]/g,
    m => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
}
function addDays(iso, n){
  const d = new Date(iso + 'T00:00:00');
  d.setDate(d.getDate() + n);
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + mm + '-' + dd;
}
function saveSim(){
  try{
    localStorage.setItem('proy_sim', JSON.stringify(SIM));
    localStorage.setItem('proy_cfg', JSON.stringify(CFG));
  }catch(e){}
}

function baseVal(){
  const v = document.getElementById('fechaBase').value;
  return v || HOY;
}
function plazoDefVal(){
  const v = parseInt(document.getElementById('plazoDef').value, 10);
  return isNaN(v) ? null : v;
}
function selPlanillas(){
  return new Set([].slice.call(document.querySelectorAll('.plsel:checked'))
    .map(c => c.value));
}

/* plazo efectivo (numero) de una factura segun simulador / planilla / default */
function plazoEff(f){
  const s = SIM[f.i] || {};
  if(s.plazo !== undefined && s.plazo !== '' && s.plazo !== null){
    const v = parseInt(s.plazo, 10);
    if(!isNaN(v)) return v;
  }
  if(f.plazo !== null && f.plazo !== undefined) return f.plazo;
  return plazoDefVal();
}
/* fecha de pago calculada */
function fechaDe(f){
  const s = SIM[f.i] || {};
  if(s.fecha) return s.fecha;
  const pl = plazoEff(f);
  if(pl === null || pl === undefined || isNaN(pl)) return null;
  return addDays(baseVal(), pl);
}
function metodoDe(f){
  const s = SIM[f.i] || {};
  return s.metodo || 'cheque';
}

/* ---------- KPIs + linea de tiempo ---------- */
function recalc(){
  const sel = selPlanillas();
  const facts = FACTURAS.filter(f => sel.has(f.p));
  const incChq = document.getElementById('chqsel').checked;

  let totCh = 0, totTr = 0;
  const byDate = {};
  const sinFecha = [];
  facts.forEach(f => {
    const met = metodoDe(f), d = fechaDe(f);
    if(met === 'transferencia') totTr += f.m; else totCh += f.m;
    if(!d){ sinFecha.push(f); return; }
    const b = byDate[d] || {ch:0, tr:0, em:0};
    if(met === 'transferencia') b.tr += f.m; else b.ch += f.m;
    byDate[d] = b;
  });
  let totEm = 0;
  if(incChq){
    CHEQUES.forEach(c => {
      const b = byDate[c.f] || {ch:0, tr:0, em:0};
      b.em += c.m; byDate[c.f] = b;
      totEm += c.m;
    });
  }

  document.getElementById('kCheque').textContent = money(totCh);
  document.getElementById('kTransf').textContent = money(totTr);
  document.getElementById('kEmit').textContent   = money(totEm);
  document.getElementById('kTotal').textContent  = money(totCh + totTr + totEm);

  const av = document.getElementById('aviso');
  if(sinFecha.length){
    av.style.display = 'block';
    av.innerHTML = '<b>' + sinFecha.length + ' factura(s)</b> de los meses '
      + 'elegidos no tienen plazo ni fecha. Carga un plazo en la fila '
      + '(o subi el "plazo por defecto") para incluirlas en el flujo.';
  } else { av.style.display = 'none'; }

  const dates = Object.keys(byDate).sort();
  let acum = 0, tl = '';
  dates.forEach(d => {
    const v = byDate[d], tot = v.ch + v.tr + v.em;
    acum += tot;
    tl += '<tr' + (d === HOY ? ' class="hoy"' : '') + '><td>' + fday(d)
      + '</td><td class="num cheque-c">' + (v.ch ? money(v.ch) : '-')
      + '</td><td class="num transf-c">' + (v.tr ? money(v.tr) : '-')
      + '</td><td class="num emit-c">' + (v.em ? money(v.em) : '-')
      + '</td><td class="num bold">' + money(tot)
      + '</td><td class="num muted">' + money(acum) + '</td></tr>';
  });
  document.getElementById('tlBody').innerHTML = tl ||
    '<tr><td colspan="6" class="muted">Sin datos para la seleccion actual.</td></tr>';
  document.getElementById('detCount').textContent = facts.length + ' factura(s)';
}

/* ---------- tabla detalle (simulador) ---------- */
function renderDetail(){
  const sel = selPlanillas();
  const facts = FACTURAS.filter(f => sel.has(f.p))
    .sort((a,b) => {
      const da = fechaDe(a) || '9999', db = fechaDe(b) || '9999';
      return da < db ? -1 : da > db ? 1 : b.m - a.m;
    });
  let dt = '';
  facts.forEach(f => {
    const s = SIM[f.i] || {};
    const plVal = (s.plazo !== undefined && s.plazo !== null) ? s.plazo
      : (f.plazo !== null && f.plazo !== undefined ? f.plazo : '');
    const fVal = s.fecha || '';
    const met = metodoDe(f);
    const dis = fVal ? ' disabled' : '';
    dt += '<tr data-id="' + esc(f.i) + '">'
      + '<td>' + esc(f.p) + '</td>'
      + '<td>' + esc(f.prest) + '</td>'
      + '<td>' + esc(f.os) + '</td>'
      + '<td class="num"><input type="number" class="e-plazo" min="0" value="'
        + plVal + '" placeholder="def"' + dis + '></td>'
      + '<td><input type="date" class="e-fecha" value="' + fVal + '"></td>'
      + '<td class="c-fpago num">' + fday(fechaDe(f)) + '</td>'
      + '<td><select class="e-met">'
        + '<option value="cheque"' + (met === 'cheque' ? ' selected' : '') + '>Cheque</option>'
        + '<option value="transferencia"' + (met === 'transferencia' ? ' selected' : '') + '>Transferencia</option>'
        + '</select></td>'
      + '<td class="num bold">' + money(f.m) + '</td></tr>';
  });
  document.getElementById('detBody').innerHTML = dt ||
    '<tr><td colspan="8" class="muted">Sin facturas para la seleccion actual.</td></tr>';
}

function renderProy(){
  renderDetail();
  recalc();
}

/* edicion en una fila del detalle */
document.getElementById('detBody').addEventListener('input', function(ev){
  const t = ev.target;
  const tr = t.closest('tr');
  if(!tr || !tr.dataset.id) return;
  const id = tr.dataset.id, f = FMAP[id];
  const s = SIM[id] || {};
  if(t.classList.contains('e-plazo')){
    if(t.value === '') delete s.plazo; else s.plazo = t.value;
  } else if(t.classList.contains('e-fecha')){
    if(t.value === '') delete s.fecha; else s.fecha = t.value;
    const pin = tr.querySelector('.e-plazo');
    if(pin) pin.disabled = !!t.value;
  } else if(t.classList.contains('e-met')){
    s.metodo = t.value;
  } else { return; }
  if(Object.keys(s).length) SIM[id] = s; else delete SIM[id];
  const cell = tr.querySelector('.c-fpago');
  if(cell) cell.textContent = fday(fechaDe(f));
  saveSim();
  recalc();
});
document.getElementById('detBody').addEventListener('change', function(ev){
  if(ev.target.classList.contains('e-met')) return;
});

/* ---------- pestana historico ---------- */
function renderHist(){
  let cant = 0, monto = 0;
  PRESTADORES.forEach(p => {
    cant += p.cheques.length;
    p.cheques.forEach(c => { monto += c.m; });
  });
  document.getElementById('hKCant').textContent  = cant;
  document.getElementById('hKMonto').textContent = money(monto);
  document.getElementById('hKPrest').textContent = PRESTADORES.length;
  document.getElementById('hKProm').textContent  = money(cant ? monto/cant : 0);

  const q = (document.getElementById('hSearch').value || '').toLowerCase();
  let rows = '';
  PRESTADORES.forEach((p, idx) => {
    if(q && p.nombre.toLowerCase().indexOf(q) === -1
         && (p.cuit || '').toLowerCase().indexOf(q) === -1) return;
    const tot = p.cheques.reduce((a,c) => a + c.m, 0);
    const meses = p.meses.length
      ? p.meses.map(m => '<span class="mes-tg">' + m + '</span>').join('')
      : '<span class="muted">sin prestacion en planillas</span>';
    rows += '<tr class="prow" data-idx="' + idx + '">'
      + '<td>' + esc(p.nombre) + '</td>'
      + '<td>' + esc(p.cuit) + '</td>'
      + '<td>' + meses + '</td>'
      + '<td class="num">' + (p.facturado ? money(p.facturado) : '-') + '</td>'
      + '<td class="num">' + p.cheques.length + '</td>'
      + '<td class="num bold">' + money(tot) + '</td></tr>';
    let sub = '<table><thead><tr><th>N&deg; cheque</th><th>Emision</th>'
      + '<th>Pago</th><th>Estado</th><th>Periodo</th><th class="num">Monto</th>'
      + '</tr></thead><tbody>';
    p.cheques.forEach(c => {
      sub += '<tr><td>' + esc(c.nro) + '</td><td>' + fday(c.femis)
        + '</td><td>' + fday(c.fpago) + '</td><td>' + esc(c.estado)
        + '</td><td>' + (esc(c.periodo) || '<span class="muted">-</span>')
        + '</td><td class="num">' + money(c.m) + '</td></tr>';
    });
    sub += '</tbody></table>';
    rows += '<tr class="subrow" style="display:none"><td colspan="6">'
      + '<div class="subwrap">' + sub + '</div></td></tr>';
  });
  document.getElementById('hBody').innerHTML = rows ||
    '<tr><td colspan="6" class="muted">Sin resultados.</td></tr>';
}
document.getElementById('hBody').addEventListener('click', function(ev){
  const tr = ev.target.closest('tr.prow');
  if(!tr) return;
  tr.classList.toggle('open');
  const sub = tr.nextElementSibling;
  if(sub && sub.classList.contains('subrow')){
    sub.style.display = sub.style.display === 'none' ? '' : 'none';
  }
});
document.getElementById('hSearch').addEventListener('input', renderHist);

/* ---------- pestanas ---------- */
document.querySelectorAll('.tab').forEach(t => {
  t.addEventListener('click', function(){
    document.querySelectorAll('.tab').forEach(x => x.classList.remove('active'));
    document.querySelectorAll('.view').forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    document.getElementById('view-' + t.dataset.view).classList.add('active');
  });
});

/* ---------- controles ---------- */
document.querySelectorAll('.plsel').forEach(c =>
  c.addEventListener('change', function(){ persistSel(); renderProy(); }));
document.getElementById('chqsel').addEventListener('change', recalc);
document.getElementById('fechaBase').addEventListener('change', function(){
  CFG.base = document.getElementById('fechaBase').value; saveSim(); renderProy();
});
document.getElementById('plazoDef').addEventListener('change', function(){
  CFG.plazoDef = document.getElementById('plazoDef').value; saveSim(); renderProy();
});
document.getElementById('selTodos').addEventListener('click', function(){
  document.querySelectorAll('.plsel').forEach(c => c.checked = true);
  persistSel(); renderProy();
});
document.getElementById('selNada').addEventListener('click', function(){
  document.querySelectorAll('.plsel').forEach(c => c.checked = false);
  persistSel(); renderProy();
});
document.getElementById('btnReset').addEventListener('click', function(){
  if(!confirm('Resetear el simulador? Se borran los plazos, fechas y metodos '
    + 'que ajustaste a mano.')) return;
  SIM = {};
  CFG = {base: HOY, plazoDef: 45};
  document.getElementById('fechaBase').value = HOY;
  document.getElementById('plazoDef').value = 45;
  saveSim();
  renderProy();
});

function persistSel(){
  try{
    const sel = [].slice.call(document.querySelectorAll('.plsel:checked'))
      .map(c => c.value);
    localStorage.setItem('proy_sel', JSON.stringify(
      {p: sel, c: document.getElementById('chqsel').checked}));
  }catch(e){}
}

/* ---------- init ---------- */
(function init(){
  try{
    const saved = JSON.parse(localStorage.getItem('proy_sel') || 'null');
    if(saved && saved.p){
      document.querySelectorAll('.plsel').forEach(c => {
        c.checked = saved.p.indexOf(c.value) !== -1;
      });
      document.getElementById('chqsel').checked = !!saved.c;
    }
  }catch(e){}
  document.getElementById('fechaBase').value = CFG.base || HOY;
  document.getElementById('plazoDef').value =
    (CFG.plazoDef !== undefined && CFG.plazoDef !== '') ? CFG.plazoDef : 45;
  renderProy();
  renderHist();
})();
</script>
</body></html>
